    @Override protected void onStart(){super.onStart();visible=true;bound=bindService(new Intent(this,MonitorService.class),connection,BIND_AUTO_CREATE);}
    @Override protected void onStop(){visible=false;if(monitor!=null){monitor.ble.stopScan();if(!prefs.getBoolean("background",true)&&!monitor.ble.operationsBusy()&&!externalFlow&&!isChangingConfigurations())monitor.pauseMonitoring();monitor.unobserve(this);}if(bound){unbindService(connection);bound=false;}monitor=null;super.onStop();}
