    private ImageButton batteryArrow(boolean next){
        ImageButton b=new ImageButton(this);b.setImageResource(next?R.drawable.ic_next_battery:R.drawable.ic_previous_battery);b.setImageTintList(new android.content.res.ColorStateList(new int[][]{new int[]{-android.R.attr.state_enabled},new int[]{}},new int[]{MUTED,ACCENT}));b.setPadding(dp(12),dp(12),dp(12),dp(12));b.setBackground(ripple(SECONDARY,12,false));b.setContentDescription(next?"Next battery":"Previous battery");b.setOnClickListener(v->cycleBattery(next?1:-1));return b;
    }
    private List<ProfileStore.Profile> switchableBatteries(){List<ProfileStore.Profile> items=new ArrayList<>();for(ProfileStore.Profile p:profiles.all())if(!p.protocol.equals("Victron"))items.add(p);return items;}
    private int selectedBatteryIndex(List<ProfileStore.Profile> items){if(!demo)for(int i=0;i<items.size();i++)if(items.get(i).address.equals(selected))return i;return -1;}
    private void updateBatterySwitcher(){
        if(batterySwitcher==null)return;List<ProfileStore.Profile> items=switchableBatteries();boolean show=(tab.equals("Overview")||tab.equals("Cells")||tab.equals("History"))&&!items.isEmpty();batterySwitcher.setVisibility(show?View.VISIBLE:View.GONE);if(!show)return;
        int index=selectedBatteryIndex(items);String name=index<0?(demo?"Demo preview":"Choose a battery"):items.get(index).name;
        boolean active=monitor!=null&&monitor.monitoring()&&selected.equals(monitor.address)&&!demo;
        String phase=demo?"Sample data":live()?"Live":active?(monitor.waitingForBattery()?"Waiting for battery":monitor.latest==null?"Connecting":"Connected"):reading==null?"No readings":"Saved";
        String position=index<0?items.size()+" saved batteries":(index+1)+" of "+items.size()+" · "+phase;
        batterySwitchName.setText(name);batterySwitchPosition.setText(position);batterySwitchPosition.setTextColor(live()?ACCENT:MUTED);batterySwitchChoice.setContentDescription(name+", "+position+". Choose battery");
        boolean busy=monitor!=null&&monitor.ble.operationsBusy();batterySwitchChoice.setEnabled(!busy);previousBattery.setEnabled(items.size()>1&&!busy);nextBattery.setEnabled(items.size()>1&&!busy);
        previousBattery.setContentDescription(items.size()>1?"Previous battery: "+items.get(index<0?items.size()-1:Math.floorMod(index-1,items.size())).name:"Previous battery");nextBattery.setContentDescription(items.size()>1?"Next battery: "+items.get(index<0?0:(index+1)%items.size()).name:"Next battery");
    }
    private void cycleBattery(int direction){List<ProfileStore.Profile> items=switchableBatteries();if(items.size()<2)return;int index=selectedBatteryIndex(items);switchBattery(items.get(index<0?(direction>0?0:items.size()-1):Math.floorMod(index+direction,items.size())));}
    private void chooseQuickBattery(){List<ProfileStore.Profile> items=switchableBatteries();if(items.isEmpty())return;String[] names=new String[items.size()];for(int i=0;i<items.size();i++)names[i]=items.get(i).name;new AlertDialog.Builder(this).setTitle("Switch battery").setSingleChoiceItems(names,selectedBatteryIndex(items),(dialog,index)->{dialog.dismiss();switchBattery(items.get(index));}).setNegativeButton("Cancel",null).show();}
    private void switchBattery(ProfileStore.Profile target){
        if(monitor!=null&&monitor.ble.operationsBusy()){toast("Wait for the battery operation to finish first");return;}
        if(!demo&&target.address.equals(selected)&&monitor!=null&&monitor.monitoring()&&target.address.equals(monitor.address))return;
        String page=tab.equals("Cells")||tab.equals("History")?tab:"Overview";
        ensureBluetooth(()->{
            if(monitor.ble.operationsBusy()){toast("Wait for the battery operation to finish first");return;}
            ProfileStore.Profile saved=profiles.get(target.address);if(saved==null||saved.protocol.equals("Victron"))return;
            String pin="";try{if(!saved.protocol.startsWith("JK"))pin=passwords.get(saved.address);}catch(Exception e){toast("Re-enter this battery's password");connectPrompt(saved.address,saved.name);return;}
            beginBatteryConnection(saved.address,saved.name,pin,page,true);
        });
    }
    private void beginBatteryConnection(String address,String name,String pin,String page,boolean showSaved){
        demo=false;selected=address;reading=null;model="";status="Connecting to "+name;
        prefs.edit().putString("last_address",address).putString("last_name",name).putString("selected_address",address).apply();
        Intent intent=new Intent(this,MonitorService.class).setAction(MonitorService.CONNECT).putExtra("address",address).putExtra("name",name).putExtra("password",pin);
        try{startForegroundService(intent);}catch(RuntimeException e){status="Could not start monitoring. Check permissions and try again.";toast(status);}
        showTab(page);if(showSaved)loadStored();
        if(Build.VERSION.SDK_INT>=33&&checkSelfPermission(Manifest.permission.POST_NOTIFICATIONS)!=PackageManager.PERMISSION_GRANTED)requestPermissions(new String[]{Manifest.permission.POST_NOTIFICATIONS},24);
    }
    private void resumeLastBattery(){
        if(!visible||demo||monitor==null||monitor.monitoring()||monitor.ble.isScanning()||!prefs.getBoolean("auto_reconnect",true))return;
        String address=prefs.getString("resume_address",prefs.getString("last_address",""));
        if(!prefs.getBoolean("resume_monitoring",!address.isEmpty())||!monitor.ble.hasPermission()||monitor.ble.adapter()==null)return;
        ProfileStore.Profile p=profiles.get(address);if(p==null||p.protocol.equals("Victron"))return;
        try{String pin=p.protocol.startsWith("JK")?"":passwords.get(address);beginBatteryConnection(address,p.name,pin,tab,true);}
        catch(Exception e){status="Reconnect paused · enter this battery's password on Connect";monitor.status=status;prefs.edit().putBoolean("resume_monitoring",false).apply();updateStatus();}
    }
    private void showTab(String next){
        tab=next;screenVersion++;fields.clear();body.removeAllViews();nav.removeAllViews();batteryActions.clear();batteryBadges.clear();batteryPhases.clear();gauge=null;chart=null;cellChart=null;cellsHolder=null;devicesHolder=null;equipmentHolder=null;victronToggle=null;balanceToggle=null;
        for(String name:new String[]{"Overview","Cells","History","Batteries","Tools"}){
            boolean active=name.equals(tab)||(name.equals("Batteries")&&tab.equals("Equipment"))||(name.equals("Tools")&&tab.equals("Parameters"));
            LinearLayout item=col();item.setGravity(Gravity.CENTER);item.setMinimumHeight(dp(64));item.setPadding(dp(3),dp(7),dp(3),dp(7));item.setBackground(ripple(active?ACTIVE:CARD,16,false));
            NavIcon icon=new NavIcon(this,name,active?ACCENT:MUTED);LinearLayout.LayoutParams iconLayout=new LinearLayout.LayoutParams(dp(24),dp(24));iconLayout.gravity=Gravity.CENTER_HORIZONTAL;item.addView(icon,iconLayout);
            TextView label=bold(name,10,active?ACCENT:MUTED);label.setGravity(Gravity.CENTER);label.setTextAlignment(View.TEXT_ALIGNMENT_CENTER);label.setPadding(0,0,0,0);label.setMaxLines(1);label.setHorizontallyScrolling(false);label.setEllipsize(TextUtils.TruncateAt.END);label.setImportantForAccessibility(View.IMPORTANT_FOR_ACCESSIBILITY_NO);
            LinearLayout.LayoutParams labelLayout=new LinearLayout.LayoutParams(-1,-2);labelLayout.topMargin=dp(5);item.addView(label,labelLayout);
            item.setContentDescription(name);item.setSelected(active);item.setFocusable(true);item.setOnClickListener(v->showTab(name));item.setAccessibilityDelegate(new View.AccessibilityDelegate(){@Override public void onInitializeAccessibilityNodeInfo(View host,android.view.accessibility.AccessibilityNodeInfo info){super.onInitializeAccessibilityNodeInfo(host,info);info.setClassName(Button.class.getName());info.setSelected(host.isSelected());}});
            nav.addView(item,new LinearLayout.LayoutParams(0,-2,1));
        }
        switch(tab){case "Cells":cellsScreen();break;case "History":historyScreen();break;case "Batteries":batteriesScreen();break;case "Equipment":equipmentScreen();break;case "Tools":toolsScreen();break;case "Parameters":parametersScreen();break;default:overview();}
        updateReading();updateStatus();scroll.scrollTo(0,0);
    }
    private void overview(){
        LinearLayout hero=card(body);LinearLayout top=row();top.addView(field("batteryname",batteryName(),20,INK),new LinearLayout.LayoutParams(0,-2,1));TextView tag=field("livebadge","OFFLINE",10,MUTED);tag.setPadding(dp(9),dp(5),dp(9),dp(5));tag.setBackground(bg(LINE,9));top.addView(tag);hero.addView(top);hero.addView(field("batterymeta","Choose a battery below",12,MUTED));gauge=new GaugeView(this);gauge.theme(INK,MUTED,ACCENT,LINE);hero.addView(gauge,new LinearLayout.LayoutParams(-1,dp(200)));hero.addView(field("remaining","No readings yet",17,INK));hero.addView(field("capacity","",12,MUTED));hero.addView(field("age","",11,MUTED));
        LinearLayout first=row();metric(first,"voltage","PACK VOLTAGE","— V");metric(first,"current","CURRENT","— A");body.addView(first);LinearLayout second=row();metric(second,"power","POWER FLOW","— W");metric(second,"delta","CELL SPREAD","— mV");body.addView(second);
        LinearLayout runtime=card(body);runtime.addView(bold("Energy & runtime",17,INK));runtime.addView(field("energy","Connect to estimate available energy",20,ACCENT));runtime.addView(field("runtime","",14,INK));runtime.addView(field("estimateNote","Estimates use reported charge and the reserve in your battery profile.",12,MUTED));
        LinearLayout states=card(body);states.addView(bold("Battery status",17,INK));states.addView(field("fets","Waiting for battery states",13,INK));states.addView(field("balance","",13,INK));balanceControls(states);states.addView(field("temp","Temperature sensors · —",14,INK));states.addView(field("cycles","",12,MUTED));states.addView(field("protection","No battery reading yet",13,MUTED));states.addView(field("localalerts","",13,AMBER));
        LinearLayout session=card(body);session.addView(bold("This connection",17,INK));session.addView(field("session","Measured energy will appear when connected",14,MUTED));wide(session,"Export connection diagnostics",false,this::exportDiagnostics);
        if(reading==null){wide(body,"Connect a battery",true,()->showTab("Batteries"));wide(body,"Try the demo",false,this::startDemo);}else if(demo)wide(body,"Leave demo & connect",true,()->{demo=false;reading=null;showTab("Batteries");});else{wide(body,"Refresh live readings",true,()->{if(monitor!=null&&monitor.monitoring()&&monitor.ble.isReady()&&selected.equals(monitor.address))monitor.ble.refresh();else if(profile()!=null)connectPrompt(selected,batteryName());else showTab("Batteries");});wide(body,"Export latest reading",false,()->exportMenu(true));}
        overviewEquipment();
    }
    private void metric(LinearLayout l,String key,String label,String value){LinearLayout c=col();c.setBackground(panel(CARD,18));c.setPadding(dp(15),dp(16),dp(10),dp(16));c.addView(text(label,10,MUTED));c.addView(field(key,value,25,INK));LinearLayout.LayoutParams p=new LinearLayout.LayoutParams(0,-2,1);p.topMargin=dp(12);if(l.getChildCount()>0)p.leftMargin=dp(10);l.addView(c,p);}
    private void updateReading(){if(reading==null){if(gauge!=null)gauge.reading(-1,"Awaiting battery");return;}JbdProtocol.Basic b=reading.basic;set("batteryname",batteryName());set("batterymeta",b.cellCount+" cells • "+(model.isEmpty()?(b.vendor.equals("JK")?b.firmware:"JBD / Xiaoxiang"):model));String flow=b.current>.1?"Charging":b.current<-.1?"Discharging":"Idle";if(gauge!=null)gauge.reading(b.soc,flow);set("remaining",fmt(b.remainingAh,1)+" Ah remaining");set("capacity","of "+fmt(b.capacityAh,1)+" Ah reported capacity");set("voltage",fmt(b.voltage,2)+" V");set("current",(b.current>0?"+":"")+fmt(b.current,2)+" A");set("power",(b.power()>0?"+":"")+fmt(b.power(),0)+" W");set("delta",fmt(reading.deltaMv(),0)+" mV");
        ProfileStore.Profile p=profile();double capacity=p!=null&&p.capacityAh>0?p.capacityAh:b.capacityAh,remaining=p!=null&&p.capacityAh>0?capacity*b.soc/100:b.remainingAh,reserve=p==null?10:p.reservePercent,volts=p!=null&&p.nominalV>0?p.nominalV:b.voltage,available=EnergyStats.availableAh(remaining,capacity,reserve);set("energy",fmt(available*volts/1000,2)+" kWh above "+fmt(reserve,0)+"% reserve");double hours=EnergyStats.runtimeHours(available,b.current);String runtime=Double.isFinite(hours)?duration(hours)+" to reserve at this load":b.current>.1&&capacity>remaining?duration((capacity-remaining)/b.current)+" to full at this charge rate":"Runtime appears while discharging";set("runtime",runtime);set("estimateNote","Approximate • assumes a steady load and BMS SOC accuracy"+(live()?"":" • last saved reading"));
        set("fets","Charging: "+(b.chargeEnabled()?"enabled":"disabled")+"    Discharging: "+(b.dischargeEnabled()?"enabled":"disabled"));int balancing=Long.bitCount(b.balanceMask);set("balance",b.balancingActive?"Balancing: active (individual flags not reported)":balancing==0?"Balancing: inactive":balancing+" cell(s) balancing");StringBuilder ts=new StringBuilder();for(int i=0;i<b.temperatures.length;i++){if(i>0)ts.append("  •  ");ts.append(b.temperatureLabels.length==b.temperatures.length?b.temperatureLabels[i]:b.vendor.equals("JK")?(i==0?"MOS":"T"+i):"T"+(i+1)).append(" ").append(temp(b.temperatures[i]));}set("temp",ts.length()==0?"Temperature readings unavailable":ts.toString());set("cycles",b.cycles+" cycles • firmware "+b.versionText()+" • built "+b.productionDate);
        String[] alarms=reading.protectionLabels();set("protection",alarms.length==0?"No active BMS protection flags":TextUtils.join("\n",alarms));if(fields.containsKey("protection"))fields.get("protection").setTextColor(alarms.length==0?ACCENT:RED);set("localalerts",monitor!=null&&selected.equals(monitor.address)?TextUtils.join("\n",monitor.alarms.active()):"");
        if(monitor!=null&&selected.equals(monitor.address)&&!demo){EnergyStats s=monitor.sessionStats;set("session","Charged "+fmt(s.chargeWh/1000,3)+" kWh • Used "+fmt(s.dischargeWh/1000,3)+" kWh\n"+fmt(s.chargeAh,2)+" Ah in • "+fmt(s.dischargeAh,2)+" Ah out\n"+duration(s.observedMs/3600000.0)+" of measured intervals");}else set("session",demo?"Demo readings are never recorded":"Connect to start a new measured session");
        if(cellChart!=null)cellChart.data(reading,INK,MUTED,ACCENT,LINE);if(cellsHolder!=null)renderCells();updateStatus();
    }
    private String duration(double hours){if(!Double.isFinite(hours)||hours<0)return "—";if(hours>240)return ">10 days";long minutes=Math.round(hours*60);return minutes>=60?minutes/60+"h "+minutes%60+"m":minutes+"m";}
    private void updateStatus(){if(statusView==null)return;updateBatteryCards();updateBatterySwitcher();updateBalanceControl();modeView.setText(demo?"DEMO • SAMPLE DATA":"YOUR BATTERY. YOUR DATA.");modeView.setTextColor(demo?AMBER:MUTED);statusView.setText(demo?"Preview only • no battery connected":monitor!=null&&monitor.victronRunning()&&!monitor.monitoring()?"Victron monitoring • Bluetooth only":monitor!=null?monitor.status:status);statusView.setTextColor(live()?ACCENT:MUTED);set("livebadge",demo?"DEMO":live()?"LIVE":"SAVED");if(fields.containsKey("livebadge"))fields.get("livebadge").setTextColor(demo?AMBER:live()?ACCENT:MUTED);if(reading!=null)set("age",demo?"Sample readings • never recorded":(live()?"Updated ":"Last reading ")+when(reading.timestamp)+" • "+Math.max(0,(System.currentTimeMillis()-reading.timestamp)/1000)+"s ago");}
