    private void refreshHistory(){if(destroyed)return;lastHistoryRefresh=System.currentTimeMillis();final int version=screenVersion;final String address=selected;final long from=System.currentTimeMillis()-historyRange;final int metric=historyMetric;io.execute(()->{try{int count=history.count(address);List<double[]> data=history.chart(address,from);EnergyStats stats=history.stats(address,from);handler.post(()->{if(destroyed||version!=screenVersion)return;if(chart!=null)chart.setData(data,metric);set("historycount",count+" saved readings for this battery • "+prefs.getInt("retention_days",30)+" day retention");set("historystats","Charged "+fmt(stats.chargeWh/1000,3)+" kWh  •  Used "+fmt(stats.dischargeWh/1000,3)+" kWh\n"+fmt(stats.chargeAh,2)+" Ah in  •  "+fmt(stats.dischargeAh,2)+" Ah out\n"+duration(stats.observedMs/3600000.0)+" measured • "+stats.samples+" samples in this period");set("historylimits",stats.samples==0?"Connect and enable recording to build history":"Voltage "+fmt(stats.minVoltage,2)+"–"+fmt(stats.maxVoltage,2)+" V\nPeak charging "+fmt(stats.peakChargeW,0)+" W • Peak use "+fmt(stats.peakDischargeW,0)+" W\nGaps longer than 90 seconds are excluded from totals.");});}catch(Exception e){handler.post(()->{if(!destroyed)toast("Could not load history");});}});}
