    private boolean isBatteryLive(String address){return monitor!=null&&monitor.monitoring()&&monitor.ble.isReady()&&address.equals(monitor.address)&&monitor.latest!=null&&System.currentTimeMillis()-monitor.latest.timestamp<=Math.max(20000,prefs.getInt("poll_seconds",5)*3000L);}
    private void updateBatteryCards(){
        if(!tab.equals("Batteries"))return;
        for(Map.Entry<String,Button> entry:batteryActions.entrySet()){
            String address=entry.getKey();boolean live=isBatteryLive(address),connecting=monitor!=null&&monitor.monitoring()&&address.equals(monitor.address)&&monitor.ble.isConnectingOrConnected()&&monitor.latest==null&&!monitor.waitingForBattery();
            boolean waiting=monitor!=null&&monitor.waitingForBattery()&&address.equals(monitor.address);
            String phase=live?"CONNECTED":waiting?"WAITING":connecting?"CONNECTING":"SAVED";if(phase.equals(batteryPhases.get(address)))continue;batteryPhases.put(address,phase);
            Button action=entry.getValue();action.setText(live?"Open dashboard":waiting?"Reconnect now":connecting?"Connecting…":"Connect");styleButton(action,live);action.setEnabled(!connecting);
            TextView badge=batteryBadges.get(address);badge.setText(phase);badge.setTextColor(live?ACCENT:MUTED);badge.setBackground(bg(live?ACTIVE:SECONDARY,8));
        }
    }
    private void select(String address){selected=address;demo=false;model="";reading=monitor!=null&&address.equals(monitor.address)?monitor.latest:null;prefs.edit().putString("selected_address",address).apply();showTab("Overview");if(reading==null)loadStored();}
    private void loadStored(){if(selected.isEmpty())return;String a=selected;io.execute(()->{Reading value=history.latest(a);handler.post(()->{if(!destroyed&&!demo&&selected.equals(a)&&!live()&&value!=null&&(reading==null||value.timestamp>reading.timestamp)){boolean first=reading==null;reading=value;if(first&&tab.equals("Overview"))showTab(tab);else updateReading();}});});}
    private void ensureBluetooth(Runnable task){if(monitor==null){toast("Bluetooth service is starting. Try again in a moment.");return;}if(!monitor.ble.hasPermission()){afterPermission=task;requestPermissions(new String[]{Manifest.permission.BLUETOOTH_SCAN,Manifest.permission.BLUETOOTH_CONNECT},21);return;}BluetoothAdapter a=monitor.ble.adapter();if(a==null){toast("No Bluetooth adapter is available");return;}if(!a.isEnabled()){afterPermission=task;externalFlow=true;startActivityForResult(new Intent(BluetoothAdapter.ACTION_REQUEST_ENABLE),22);return;}task.run();}
    private void scan(){ensureBluetooth(()->{if(monitor.ble.isScanning()){monitor.ble.stopScan();showTab("Batteries");return;}if(monitor.monitoring())monitor.stopMonitoring();devices.clear();monitor.ble.startScan();showTab("Batteries");});}
    private void renderDevices(){if(devicesHolder==null)return;devicesHolder.removeAllViews();List<DeviceItem> found=new ArrayList<>(devices.values());found.sort((a,b)->a.likely==b.likely?Integer.compare(b.rssi,a.rssi):Boolean.compare(b.likely,a.likely));set("devicecount",found.isEmpty()?"Scan to find a new battery":found.size()+" nearby devices • BMS candidates first");for(DeviceItem d:found){LinearLayout c=card(devicesHolder);c.addView(bold(d.name,16,INK));c.addView(text((d.likely?"BMS candidate • ":"")+d.rssi+" dBm",12,MUTED));wide(c,"Connect",d.likely,()->{try{String a=d.device.getAddress();if(nearbyVictron.containsKey(a))addVictron(a,d.name);else connectPrompt(a,d.name);}catch(SecurityException e){toast("Allow Nearby devices");}});}}
    private void connectPrompt(String address,String label){if(monitor!=null&&monitor.ble.operationsBusy()){toast("Wait for the battery operation to finish first");return;}ensureBluetooth(()->{ProfileStore.Profile p=profiles.get(address);String name=p==null?label:p.name;LinearLayout form=col();form.setPadding(dp(20),dp(12),dp(20),dp(10));form.addView(text("Battery: "+name,16,INK));String[] kinds={"Auto","JBD","JK02_24S","JK02_32S"};Spinner kind=choice(form,"BMS protocol",kinds,p==null?0:Math.max(0,Arrays.asList(kinds).indexOf(p.protocol)),null);EditText password=input(form,"JBD battery password (six characters)","",false);password.setInputType(InputType.TYPE_CLASS_TEXT|InputType.TYPE_TEXT_VARIATION_PASSWORD);password.setSingleLine(true);password.setFilters(new InputFilter[]{new InputFilter.LengthFilter(6)});try{password.setText(passwords.get(address));}catch(Exception e){toast("Re-enter this battery's password");}CheckBox remember=check(form,"Remember encrypted password for quick switching",prefs.getBoolean("remember_password",false),null);form.addView(text("Leave empty for JK telemetry. Auto detects JBD or supported JK02 formats. JK02_24S and JK02_32S describe the packet format, not your battery’s cell count.",12,MUTED));AlertDialog dialog=new AlertDialog.Builder(this).setTitle("Connect battery").setView(form).setNegativeButton("Cancel",null).setPositiveButton("Connect",null).create();dialog.setOnShowListener(v->dialog.getButton(AlertDialog.BUTTON_POSITIVE).setOnClickListener(w->{String pin=password.getText().toString();try{if(!kind.getSelectedItem().toString().startsWith("JK"))JbdAuthentication.validatePassword(pin);else pin="";ProfileStore.Profile saved=p==null?new ProfileStore.Profile(address,name):p;saved.protocol=kind.getSelectedItem().toString();profiles.put(saved);if(remember.isChecked())passwords.put(address,pin);else passwords.remove(address);}catch(IllegalArgumentException|JSONException e){toast(e.getMessage());return;}catch(Exception e){toast("Password could not be saved; connection will still use it");}prefs.edit().putBoolean("remember_password",remember.isChecked()).apply();dialog.dismiss();beginBatteryConnection(address,name,pin,"Overview",false);}));dialog.show();});}
    private void editProfile(ProfileStore.Profile p){LinearLayout f=col();f.setPadding(dp(20),dp(12),dp(20),dp(10));EditText name=input(f,"Battery name",p.name,false);String[] chemistry={"Unknown / other","LiFePO₄","Lithium ion","Lead acid","Other"};Spinner chem=choice(f,"Chemistry (label only)",chemistry,Math.max(0,Arrays.asList(chemistry).indexOf(p.chemistry)),null);String[] protocols={"Auto","JBD","JK02_24S","JK02_32S","Victron"};Spinner proto=choice(f,"Device protocol",protocols,Math.max(0,Arrays.asList(protocols).indexOf(p.protocol)),null);f.addView(text("JK02_24S and JK02_32S describe the packet format, not the cell count. Use Auto if unsure.",12,MUTED));EditText capacity=input(f,"Capacity override (Ah, 0 = BMS)",fmt(p.capacityAh,1),true),volts=input(f,"Nominal voltage (V, 0 = measured)",fmt(p.nominalV,1),true),reserve=input(f,"Reserve for runtime estimate (%)",fmt(p.reservePercent,0),true),notes=input(f,"Notes",p.notes,false);notes.setSingleLine(false);notes.setMinLines(2);notes.setFilters(new InputFilter[]{new InputFilter.LengthFilter(2000)});f.addView(text("These values affect labels and estimates on this phone.",12,MUTED));ScrollView sv=new ScrollView(this);sv.addView(f);AlertDialog d=new AlertDialog.Builder(this).setTitle("Battery profile").setView(sv).setNegativeButton("Cancel",null).setNeutralButton("Remove profile",(x,w)->new AlertDialog.Builder(this).setTitle("Remove saved profile?").setMessage("Its readings remain in History. The saved password will be removed from this phone.").setNegativeButton("Keep",null).setPositiveButton("Remove",(a,b)->{profiles.remove(p.address);passwords.remove(p.address);passwords.remove("victron:"+p.address);showTab(tab);}).show()).setPositiveButton("Save",null).create();d.setOnShowListener(v->d.getButton(-1).setOnClickListener(w->{try{JSONObject j=p.json();j.put("name",name.getText().toString().trim());j.put("chemistry",chem.getSelectedItem().toString());j.put("protocol",proto.getSelectedItem().toString());j.put("capacity_ah",num(capacity));j.put("nominal_v",num(volts));j.put("reserve_percent",num(reserve));j.put("notes",notes.getText().toString());ProfileStore.Profile next=ProfileStore.Profile.parse(j);profiles.put(next);if(monitor!=null)monitor.settingsChanged();d.dismiss();showTab(tab);}catch(Exception e){toast("Check the profile values: "+e.getMessage());}}));d.show();}
    private double num(EditText e){double n=Double.parseDouble(e.getText().toString().trim());if(!Double.isFinite(n))throw new IllegalArgumentException("Enter a finite number");return n;}
    private EditText input(LinearLayout l,String label,String value,boolean number){l.addView(text(label,12,MUTED));EditText e=new EditText(this);e.setTextColor(INK);e.setHintTextColor(MUTED);e.setText(value);e.setSingleLine(true);e.setInputType(number?InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL|InputType.TYPE_NUMBER_FLAG_SIGNED:InputType.TYPE_CLASS_TEXT);e.setMinHeight(dp(48));e.setContentDescription(label);l.addView(e,new LinearLayout.LayoutParams(-1,-2));return e;}
