    private void toolsScreen(){body.addView(bold("Make it yours",24,INK));body.addView(text("Everything here works on the phone without an account or cloud service.",13,MUTED));LinearLayout display=card(body);display.addView(bold("Display",17,INK));String[] themes={"Dark","Light","System"};choice(display,"Theme",themes,Math.max(0,Arrays.asList(themes).indexOf(prefs.getString("theme","Dark"))),i->{prefs.edit().putString("theme",themes[i]).apply();externalFlow=true;recreate();});check(display,"Temperatures in Fahrenheit",prefs.getBoolean("fahrenheit",false),v->{prefs.edit().putBoolean("fahrenheit",v).apply();updateReading();});check(display,"Keep screen awake while viewing",prefs.getBoolean("keep_awake",false),v->{prefs.edit().putBoolean("keep_awake",v).apply();keepAwake();});
        LinearLayout recording=card(body);recording.addView(bold("Monitoring & recording",17,INK));check(recording,"Continue monitoring with the screen off",prefs.getBoolean("background",true),v->prefs.edit().putBoolean("background",v).apply());check(recording,"Reconnect automatically when back in range",prefs.getBoolean("auto_reconnect",true),v->{prefs.edit().putBoolean("auto_reconnect",v).apply();if(monitor!=null)monitor.settingsChanged();if(v)resumeLastBattery();});check(recording,"Record real readings on this phone",prefs.getBoolean("record",true),v->prefs.edit().putBoolean("record",v).apply());int[] poll={5,10,30};choice(recording,"Read battery every",new String[]{"5 seconds","10 seconds","30 seconds"},index(poll,prefs.getInt("poll_seconds",5)),i->{prefs.edit().putInt("poll_seconds",poll[i]).apply();if(monitor!=null)monitor.settingsChanged();});int[] sample={5,10,30,60};choice(recording,"Save a sample every",new String[]{"5 seconds","10 seconds","30 seconds","60 seconds"},index(sample,prefs.getInt("sample_seconds",10)),i->prefs.edit().putInt("sample_seconds",sample[i]).apply());recording.addView(text("Saved samples cannot be more frequent than Bluetooth reads. Automatic reconnect waits for the last connected battery and refreshes it when back in range. Keep screen-off monitoring enabled to reconnect in the background. Stop monitoring cancels reconnecting. Monitoring uses phone battery and has a notification with a Stop button.",12,MUTED));int[] retention={7,30,90};choice(recording,"Keep history (older samples are removed)",new String[]{"7 days","30 days","90 days"},index(retention,prefs.getInt("retention_days",30)),i->{prefs.edit().putInt("retention_days",retention[i]).apply();io.execute(()->history.prune(retention[i]));});recording.addView(text("Storage is capped at roughly 260,000 readings per history type.",11,MUTED));
        LinearLayout battery=card(body);battery.addView(bold("Battery tools",17,INK));battery.addView(text(batteryName(),13,MUTED));wide(battery,"BMS parameters",true,()->showTab("Parameters"));wide(battery,"Edit battery profile",false,()->{ProfileStore.Profile p=profile();if(p==null)toast("Save or connect a battery first");else editProfile(p);});wide(battery,"Configure this battery's alerts",false,this::editAlerts);wide(battery,"Load & runtime calculator",false,this::calculator);wide(battery,"Export offline battery report",false,this::report);
        LinearLayout data=card(body);data.addView(bold("Your data",17,INK));wide(data,"Back up profiles & readings",true,()->{exportKind="backup";startExport("application/json","Offline-BMS-backup-"+stamp()+".json");});wide(data,"Restore a backup",false,()->{externalFlow=true;try{startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).addCategory(Intent.CATEGORY_OPENABLE).setType("application/json"),31);}catch(ActivityNotFoundException e){externalFlow=false;toast("No file picker is available");}});data.addView(text("Backup files contain battery names, notes and readings, including Victron equipment. Passwords and readout keys stay on this phone. Restoring merges readings and adds missing profiles; existing profiles are kept.",12,MUTED));wide(data,"Export all recorded history",false,()->{exportAddress="";exportFrom=0;exportMenuForAll();});wide(data,"Delete selected battery's history",false,()->new AlertDialog.Builder(this).setTitle("Delete this battery's history?").setMessage(batteryName()+": readings, sessions and saved events will be removed from this phone.").setNegativeButton("Keep",null).setPositiveButton("Delete",(d,w)->{String address=selected;if(address.isEmpty())return;io.execute(()->{history.clear(address);handler.post(()->{if(!destroyed)toast("Battery history deleted");});});}).show());wide(data,"Forget passwords & Victron readout keys",false,()->{passwords.clear();prefs.edit().putBoolean("remember_password",false).apply();toast("Saved passwords and readout keys removed from this phone");});supportCard();wide(body,"App details & diagnostics",false,this::details);wide(body,"Offline user guide",false,()->info("Using Offline BMS","Batteries\nScan, enter the battery password and connect. Give each battery a name in its profile. Use the top arrows on Overview, Cells or History to switch and connect a saved battery. Tap the name to choose directly. One battery is live at a time. Remember its encrypted password on Connect for quick switching.\n\nOverview\nPositive current and power mean charging. Negative values mean discharging. Saved readings are labelled with their age. Runtime is an estimate to your chosen reserve.\n\nCells\nThe chart adapts its scale to highlight small differences. Green cells are reported as balancing. The Balance button reads and enables/disables automatic balancing on supported JK02 or classic JBD devices. Existing voltage and cell-difference limits remain in effect. Changes are reviewed and read back. This is not a state-of-health test.\n\nHistory\nChoose a battery and time range. Drag on graphs to inspect points. Energy is integrated only across measured intervals up to 90 seconds, within the same session. Missing intervals are excluded.\n\nAlerts\nConfigure per battery. Thresholds need two consecutive readings; BMS protection flags are immediate. Recovery uses a small hysteresis margin. Enable Android notifications for alerts with the screen off. Alerts require this phone to be connected and running.\n\nBackground recording\nEnabled by default, with a persistent monitoring notification. Stop monitoring from Batteries or the notification. Bluetooth range and Android power management can interrupt it. Automatic reconnect is enabled by default. When the battery goes out of range, the notification shows Waiting for battery; live readings resume when it returns. Stop monitoring cancels reconnecting. Opening the app resumes the last battery unless you stopped monitoring. No monitoring starts automatically after reboot or force-stop; open the app to resume.\n\nBackups\nUse a local folder for offline exports. Backup restores merge profiles and readings; passwords, event lists and session summaries are not backed up. Graphs and energy totals remain available from restored readings.\n\nBMS settings\nProfiles and alerts are local app settings. Tools → BMS parameters can read and edit supported JBD battery settings. Read current values first and review each individual edit. Saving also resets the BMS protection counters; their original values are preserved in the local pre-write snapshot. Other profiles and alerts are phone settings. Calibration, MOSFET controls and password changes are not included."));}
    private int index(int[] values,int n){for(int i=0;i<values.length;i++)if(values[i]==n)return i;return 0;}
